#include <iostream>
#include <string>
#include <algorithm>
#include <cstdlib>

using namespace std;

int main() {
    string word;
    cin >> word;

    int selectedIndex = 13;
    long long result = 0;

    for (char c : word) {
        int targetIndex = (c - 'a' + 13) % 26;
        int distance = abs(targetIndex - selectedIndex);
        result += min(distance, 26 - distance);
        selectedIndex = targetIndex;
    }

    cout << result << '\n';
    return 0;
}

